concepts.code:
// 1. Hoisting — what the engine actually sees
console.log(name); // undefined (not ReferenceError)
console.log(greet); // [Function: greet] — fully hoisted
// console.log(age); // ReferenceError — TDZ

var name = 'Rahul';
function greet() { return 'hello'; }
let age = 25;

// 2. Execution context — this binding
function showContext() {
  console.log(this); // depends on call site
}
showContext(); // global (sloppy) or undefined (strict)

// 3. Scope chain in action
const city = 'Mumbai';
function outer() {
  const country = 'India';
  function inner() {
    // inner can see city + country via scope chain
    console.log(city, country);
  }
  inner();
}
outer();

// 4. TDZ trap
function tdz() {
  // console.log(x); // ReferenceError
  let x = 10;
  console.log(x); // 10
}

// 5. Stack overflow
function infinite() {
  return infinite(); // RangeError: Maximum call stack exceeded
}
// Fix: add base case or use trampolining

concepts.bugs:
BUG 1 — Hoisting trap:
var total = price * 1.18; // NaN — price is undefined (hoisted but not yet assigned)
var price = 100;
Fix: always declare before use, prefer let/const.

BUG 2 — TDZ access:
function setup() {
  console.log(config); // ReferenceError
  let config = {};
}
Fix: move let/const declarations to top of block.

BUG 3 — Variable shadowing:
let count = 0;
function increment() {
  let count = 1; // shadows outer count
  count++;
}
increment();
console.log(count); // 0 — outer untouched
Fix: rename inner variable.

BUG 4 — Infinite recursion:
function factorial(n) {
  return n * factorial(n - 1); // missing base case
}
Fix: add if (n <= 1) return 1;

