concepts.deep:
In V8, when a function is created inside another function and references outer variables, V8 allocates a HeapClosure object on the heap — not the stack. The inner function gets a pointer to this heap object. This is why closures can outlive their parent function.

Only variables that are actually referenced get closed over — V8 is smart enough not to capture everything.

The MODULE PATTERN uses closures to create private state:
const counter = (() => {
  let count = 0; // private — not accessible outside
  return { increment: () => ++count, get: () => count };
})();

React's useState is essentially a closure over an array slot in a fiber node. Each render creates a new closure that captures the current state value — which is why hooks must be called in the same order every render.

concepts.code:
// 1. Basic closure
function makeCounter(start = 0) {
  let count = start; // lives in closure
  return () => ++count;
}
const counter = makeCounter(10);
console.log(counter()); // 11
console.log(counter()); // 12

// 2. Classic loop bug + 3 fixes
// BUG:
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // 3, 3, 3
}
// FIX 1: let (block scoped)
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // 0, 1, 2
}
// FIX 2: IIFE
for (var i = 0; i < 3; i++) {
  ((j) => setTimeout(() => console.log(j), 100))(i);
}

// 3. Debounce — a practical closure
function debounce(fn, delay) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
const search = debounce((q) => console.log('Searching:', q), 300);

// 4. Memoize
function memoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

// 5. Once — run only the first time
function once(fn) {
  let called = false, result;
  return function(...args) {
    if (!called) { called = true; result = fn.apply(this, args); }
    return result;
  };
}

concepts.bugs:
BUG 1 — Memory leak via closure:
function attachHandler() {
  const largeData = new Array(1000000).fill('x');
  button.addEventListener('click', () => {
    console.log(largeData.length); // largeData never GC'd
  });
}
Fix: store only what you need, or remove listener when done.

BUG 2 — Stale closure in React:
const [count, setCount] = useState(0);
useEffect(() => {
  const id = setInterval(() => {
    setCount(count + 1); // always adds to initial 0
  }, 1000);
  return () => clearInterval(id);
}, []); // missing count in deps
Fix: setCount(prev => prev + 1) or add count to deps.

BUG 3 — Shared mutable state:
function makeAdder(x) {
  return (y) => x + y;
}
const add5 = makeAdder(5);
// Fine here. But if x were an object, mutations would be shared.

